// ============================================
// Article files: load once, fetch ahead of the tap
// ============================================
// Each article lives in its own small file (./articles/<slug>.js, generated by
// scripts/gen-blog-meta.mjs). Opening an article used to start two downloads
// only AFTER the tap, one after the other: the article page's code, then the
// article. On a weak signal that meant seconds of "Loading…" (reported after
// a voice search). Now the blog list calls prefetchArticle() for the
// suggestions on screen and for any card the finger touches, so by the time
// the page opens the article is usually already on the phone.

const BODIES = import.meta.glob('./articles/*.js');
const pending = new Map(); // slug → Promise<body|null>
const ready = new Map();   // slug → body (already downloaded)

export const hasArticle = (slug) => Boolean(BODIES[`./articles/${slug}.js`]);

// The downloaded article, or undefined — lets the page draw it instantly.
export const readyArticle = (slug) => ready.get(slug);

export function loadArticleBody(slug) {
  if (ready.has(slug)) return Promise.resolve(ready.get(slug));
  if (pending.has(slug)) return pending.get(slug);
  const load = BODIES[`./articles/${slug}.js`];
  if (!load) return Promise.resolve(null);
  const p = load()
    .then((m) => { ready.set(slug, m.default); pending.delete(slug); return m.default; })
    // Failed (e.g. signal dropped): forget it so opening the article retries.
    .catch((e) => { pending.delete(slug); throw e; });
  pending.set(slug, p);
  return p;
}

// The article page's own code (same file App.jsx lazy-loads; downloaded once).
let pageCode = null;
export function prefetchArticlePage() {
  if (!pageCode) pageCode = import('./BlogArticle').catch(() => { pageCode = null; });
  return pageCode;
}

// Start both downloads in the background. Never throws.
export function prefetchArticle(slug) {
  if (!slug || !hasArticle(slug)) return;
  prefetchArticlePage();
  loadArticleBody(slug).catch(() => {});
}
